def build_remaining_cases():
    cases = []
    for row in REMAINING_SPECS:
        (cid, spec, title, setting, pname, age, gender, occ, comp, vitals, cues,
         soc_resp, rf1_k, rf1_t, rf1_r, rf2_k, rf2_t, rf2_r, pmhx_r, soc_r, ice_r,
         pert_t, pert_d, pert_f, primary_dx, mnm_dx, sec_dx, viva1_q, viva1_r, viva2_r) = row
        voice = "en-SG-WayneNeural" if gender == "Male" else "en-SG-LunaNeural"
        c = make_station(
            case_id=cid, specialty=spec, title=title, setting=setting,
            patient_name=pname, age=age, gender=gender, occupation=occ,
            complaint=comp, vitals=vitals, voice_id=voice, cues=cues,
            socrates_trig=["pain", "start", "onset", "symptoms", "what", "when", "describe"],
            socrates_resp=soc_resp,
            rf1_key=rf1_k, rf1_trig=rf1_t, rf1_resp=rf1_r,
            rf2_key=rf2_k, rf2_trig=rf2_t, rf2_resp=rf2_r,
            pmhx_trig=["medical", "history", "meds", "drugs", "past", "diabetes", "bp"],
            pmhx_resp=pmhx_r,
            social_trig=["smoke", "alcohol", "job", "work", "family", "live"],
            social_resp=soc_r,
            ice_resp=ice_r,
            pert_title=pert_t, pert_desc=pert_d, pert_findings=pert_f,
            pert_shifts={primary_dx: 2, mnm_dx: -2, sec_dx: -1},
            pert_rationale=f"{pert_t} confirms {primary_dx} and rules out {mnm_dx}.",
            primary_dx=primary_dx,
            primary_sup=[comp, rf1_r[:90], pert_d[:90]],
            mnm_dx=mnm_dx, mnm_sup=["Overlapping acute presentation"], mnm_ref=[f"Excluded by {pert_t}"],
            sec_dx=sec_dx, sec_sup=["Initial differential consideration"],
            viva1_q=viva1_q, viva1_rubric=viva1_r,
            viva1_keys=[s.strip() for s in viva1_r.split(";")[:2] if s.strip()],
            viva2_q=f"Outline your immediate management plan for {primary_dx}.",
            viva2_rubric=viva2_r,
            viva2_keys=[s.strip() for s in viva2_r.split(";")[:3] if s.strip()],
            trap_name=f"Missing Key Red Flag or Delaying Definitive Action in {primary_dx}",
            trap_desc=f"Failing to elicit {rf1_k} or delaying targeted management.",
            trap_cond="Candidate misses critical red flags or omits first-line life/organ-saving action.",
            trap_rem=viva1_r[:140]
        )
        cases.append(c)
    return cases

if __name__ == "__main__":
    rem = build_remaining_cases()
    print(f"Built {len(rem)} remaining cases (56-100).")
